def make_proxied_client(proxy_url: str, base_url: str) -> httpx.Client:
    """Return an httpx.Client for base_url routing all requests through proxy_url.

    Requests use a 5-second timeout and have the User-Agent header set to 'inventory-sync/1.0'.
    """
    headers = {"User-Agent": "inventory-sync/1.0"}
    timeout = 5.0
    # Use ProxyTransport from httpx 0.28+ to route all requests through the proxy_url
    transport = httpx.ProxyTransport.from_url(proxy_url)
    return httpx.Client(base_url=base_url, headers=headers, timeout=timeout, transport=transport)

