import httpx


def make_proxied_client(proxy_url: str, base_url: str) -> httpx.Client:
    """
    Create an httpx.Client for the given base_url that sends all HTTP and HTTPS requests
    through the HTTP proxy at proxy_url, with a 5-second timeout and a fixed User-Agent header.

    Args:
        proxy_url: The URL of the HTTP proxy to use for all requests.
        base_url: The base URL for the client.

    Returns:
        An httpx.Client instance configured as specified.
    """
    proxies = {
        "http://": proxy_url,
        "https://": proxy_url,
    }
    headers = {
        "User-Agent": "inventory-sync/1.0"
    }
    timeout = httpx.Timeout(5.0)

    return httpx.Client(base_url=base_url, proxies=proxies, headers=headers, timeout=timeout)

